import math

SCENARIOS = [
    (4, 80, 50, 2, 10),
    (7, 20, 50, 2, 10),
    (3, 90, 50, 2, 5),
]

def desired_capacity(current, metric, target, min_c, max_c):
    raw = math.ceil(current * metric / target)
    return max(min_c, min(max_c, raw))

for current, metric, target, min_c, max_c in SCENARIOS:
    raw = math.ceil(current * metric / target)
    clamped = desired_capacity(current, metric, target, min_c, max_c)
    line = f"cpu={metric}% current={current} -> desired={clamped}"
    if raw > max_c:
        line += " (clamped to max)"
    print(line)
